  const giveUp = () => {
    copy.remove();
    if (copies.get(element) === copy) {
      copies.delete(element);
    }
  };
  if (!show()) {
    // Refused during the closing popover's toggle: hidden until it is over.
    view.queueMicrotask(() => {
      if (!copy.isConnected || show()) {
        return;
      }
      view.requestAnimationFrame(() => {
        if (copy.isConnected && !show()) {
          giveUp();
        }
      });
    });
