const TRANSFORM_PROPERTIES = ['transform', 'translate', 'scale', 'rotate'];

/** A 2D affine matrix in the order CSS `matrix()` lists it: a, b, c, d, e, f. */
type Matrix2D = readonly [number, number, number, number, number, number];

