    throw new Error(
      `motion role "${id}" must be a dotted table path such as "springs.sheetPresent"`,
    );
  }
  return `--motion-${id
    .split('.')
    .map(part => part.replace(/[A-Z]/g, c => `-${c.toLowerCase()}`))
    .join('-')}`;
